import { Hydrator, Orm, RelationForeignKey, SchemaBuilder } from '../../src'
import { drizzle } from 'drizzle-orm/node-postgres'
import { Pool } from 'pg'
import { Friendship, Person, TransferRule, WalletType } from '../fixtures/multiRefModels'

// A real drizzle instance so the statement is generated by drizzle itself: the join a relation
// compiles to is the only proof that it resolved to the right column. The pool never connects.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
let db: any

beforeAll(() => {
    db = drizzle(new Pool({ host: 'localhost' }), { schema: SchemaBuilder.build() })
})

beforeEach(() => {
    jest.restoreAllMocks()
    jest.spyOn(Orm, 'conn').mockReturnValue(db)
})

describe('belongsTo with an explicit foreign key', () => {
    const sqlFor = (as: string): string =>
        TransferRule.query().includeModel(WalletType, { as }).endInclude().toSQL().sql

    it('two relations to the same model join through their own columns', () => {
        expect(sqlFor('sourceWalletType')).toContain('"id" = "transfer_rules"."source_wallet_type_id"')
        expect(sqlFor('targetWalletType')).toContain('"id" = "transfer_rules"."target_wallet_type_id"')
    })

    it('neither relation borrows the column of the other', () => {
        expect(sqlFor('sourceWalletType')).not.toContain('= "transfer_rules"."target_wallet_type_id"')
        expect(sqlFor('targetWalletType')).not.toContain('= "transfer_rules"."source_wallet_type_id"')
    })

    it('resolves a self-reference through the named column', () => {
        const parent = Person.query().includeModel(Person, { as: 'parent' }).endInclude().toSQL().sql
        const sponsor = Person.query().includeModel(Person, { as: 'sponsor' }).endInclude().toSQL().sql
        expect(parent).toContain('"id" = "people"."parent_id"')
        expect(sponsor).toContain('"id" = "people"."sponsor_id"')
    })
})

describe('hasMany with an explicit foreign key', () => {
    const sqlFor = (as: string): string =>
        WalletType.query().includeModel(TransferRule, { as }).endInclude().toSQL().sql

    it('joins on the column the relation names, not on the first one found', () => {
        expect(sqlFor('outgoingRules')).toContain('"source_wallet_type_id" = "wallet_types"."id"')
        expect(sqlFor('incomingRules')).toContain('"target_wallet_type_id" = "wallet_types"."id"')
    })

    it('neither relation borrows the column of the other', () => {
        expect(sqlFor('outgoingRules')).not.toContain('"target_wallet_type_id" = "wallet_types"."id"')
        expect(sqlFor('incomingRules')).not.toContain('"source_wallet_type_id" = "wallet_types"."id"')
    })

    it('resolves a self-referencing hasMany', () => {
        const children = Person.query().includeModel(Person, { as: 'children' }).endInclude().toSQL().sql
        expect(children).toContain('"parent_id" = "people"."id"')
        expect(children).not.toContain('"sponsor_id" = "people"."id"')
    })

    it('a required include filters on the named column too', () => {
        const sql = WalletType.query()
            .include({ model: TransferRule, as: 'incomingRules', required: true })
            .toSQL().sql
        expect(sql).toContain('"transfer_rules"."target_wallet_type_id" = "wallet_types"."id"')
        expect(sql).not.toContain('"transfer_rules"."source_wallet_type_id" = "wallet_types"."id"')
    })
})

describe('belongsToMany through a junction that references one model twice', () => {
    const friends = (): string => Person.query().includeModel(Person, { as: 'friends' }).endInclude().toSQL().sql

    it('reaches the junction through { foreignKey }', () => {
        expect(friends()).toContain('"people_friends"."person_id" = "people"."id"')
    })

    it('reaches the target through { otherKey }', () => {
        expect(friends()).toContain('"id" = "people_friends"."friend_id"')
    })

    it('hydrates the junction rows through the otherKey side', () => {
        const person = Hydrator.hydrate(Person, {
            id: 1,
            friends: [{ id: 10, personId: 1, friendId: 2, friend: { id: 2, name: 'Ada' } }],
        }) as Person
        expect(person.friends.map(f => f.name)).toEqual(['Ada'])
    })

    it('picks the junction relation by column name, property or database, not by declaration order', () => {
        expect(RelationForeignKey.junctionRelation(Friendship.meta, Person, 'friendId')?.propertyKey).toBe('friend')
        expect(RelationForeignKey.junctionRelation(Friendship.meta, Person, 'personId')?.propertyKey).toBe('person')
        expect(RelationForeignKey.junctionRelation(Friendship.meta, Person, 'friend_id')?.propertyKey).toBe('friend')
    })
})
